  fill(204);

  monShader = createShader(vert, frag);
  }

function draw() {  
  this.shader(monShader);
  background(135,254,254);
  monShader.setUniform('resolution',[width,height]);
  monShader.setUniform('time',millis()*0.001);
  box(width,height,1);
}

// save jpg
