var frag=`

#ifdef GL_ES
precision highp float;
#endif

uniform vec2 resolution;
uniform float time;

vec4 quaternion(vec3 axis, float theta){
  return vec4(axis*sin(theta/2.0),cos(theta/2.0));}


vec3 qtourne(vec4 q, vec3 v){
return v+2.0*cross(cross(v,q.xyz)-q.w*v,q.xyz);}


void main(void)
{
    vec2 pos = -1.0 + 2.0 * gl_FragCoord.xy / resolution.xy;
    float tempo =10.0+ 15.0*cos(time*0.01);
   vec3 pos3=vec3(pos*sin(tempo),pos.y*pos.x*cos(tempo));
   pos3.z=cos(pos3.z*sin(pos3.x));
    float tux=1.0*pos3.x;
    float tuy=0.5*pos3.y;
    float tiy=200.0*sin(tux+tempo);
    float tix=200.0*cos(tuy+tempo);
   float ray=pow(pow(abs(tix),0.4),2.8);
    vec3 cv1=vec3(cos(pos3.x*ray*0.2),0.1* cos(pos3.y*ray*3.0) ,2.0*cos(pos3.z*ray*0.2));

  cv1=vec3(floor(100.0*cv1.x),floor(100.0*cv1.y),floor(100.0*cv1.z));
  vec3 axx=normalize(vec3(sin(time),1.0,3.0*cos(time)));
  vec4 qoo=quaternion(axx, sin(time*2.6));
  vec3 cvv=qtourne(qoo,cv1);
  cvv=qtourne(qoo,cvv);
    gl_FragColor=vec4(cvv,1.0);
}`;

